    RrhhEmpleado = apps.get_model("rrhh", "RrhhEmpleado")
    RrhhPuesto = apps.get_model("rrhh", "RrhhPuesto")
    for e in EMPLEADOS:
        RrhhEmpleado.objects.get_or_create(
            id_empleado=e["id_empleado"],
            defaults={k: v for k, v in e.items() if k != "id_empleado"},
        )
    for p in PUESTOS:
        id_puesto = p["id_puesto"]
        defaults = {k: v for k, v in p.items() if k not in ("id_puesto", "id_supervisor")}
        # La FK al empleado se llama "empleado_id" en Django, no "id_empleado"
        defaults["empleado_id"] = defaults.pop("id_empleado")
        RrhhPuesto.objects.get_or_create(id_puesto=id_puesto, defaults=defaults)


